window.appendNewAction = function () {
    const titleEl = document.getElementById('add-act-title');
    const descEl = document.getElementById('add-act-desc');
    const colorEl = document.getElementById('add-act-color');
    const iconEl = document.getElementById('add-act-icon');
    const trackEl = document.getElementById('add-act-track');

    const title = titleEl ? titleEl.value.trim() : '';
    const desc = descEl ? descEl.value.trim() : '';
    const color = colorEl ? colorEl.value : 'indigo';
    const icon = iconEl ? iconEl.value : 'generic';
    const track = trackEl ? trackEl.value : '';

    if (!title) return showToast("Action title required.", "error");

    if (!Array.isArray(window.customActions)) {
        window.customActions = [];
    }

    if (window.customActions.some(a => (a.title || '').toLowerCase() === title.toLowerCase())) {
        return showToast("Daily Action Tracker with this title already exists.", "error");
    }

    const slug = 'act_' + (title.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/(^_|_$)/g, '') || Date.now());
    const nextPriority = window.customActions.length + 1;

    const newAction = {
        id: slug,
        title: title,
        question: desc || `Did you complete ${title}?`,
        color: color,
        icon: icon,
        track: track,
        priority: nextPriority,
        order: nextPriority
    };

    window.customActions.push(newAction);

    if (Array.isArray(window.tasks)) {
        window.tasks.forEach(t => {
            if (t[newAction.id] === undefined) t[newAction.id] = false;
        });
    }

    if (titleEl) titleEl.value = '';
    if (descEl) descEl.value = '';

    if (window.FirebaseService && typeof window.FirebaseService.saveToCloud === 'function') {
        window.FirebaseService.saveToCloud();
    }

    renderUI();
    showToast("Daily Action Tracker created & added to The X Commitments!", "success");
};

window.appendNewProgram = function () {
    const track = document.getElementById('add-prog-track').value;
    const name = document.getElementById('add-prog-name').value.trim();
    if (!name) return showToast("Program name required.", "error");
    window.customPrograms[track] = window.customPrograms[track] || [];
    if (window.customPrograms[track].some(p => (p.name || p).toLowerCase() === name.toLowerCase())) return showToast("Program already exists.", "error");

    const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
    const nextOrder = window.customPrograms[track].length;
    window.customPrograms[track].push({
        id: slug || 'prog-' + Date.now(),
        name: name,
        priority: 3,
        order: nextOrder,
        targetCGPA: ''
    });
    window.sortAllCustomData();

    document.getElementById('add-prog-name').value = '';
    FirebaseService.saveToCloud(); renderUI(); showToast("Program successfully added!", "success");
};

window.appendNewSubject = function () {
    const track = document.getElementById('add-sub-track').value;
    const prog = document.getElementById('add-sub-program').value;
    const name = document.getElementById('add-sub-name').value.trim();
    const doBulk = document.getElementById('add-sub-bulk-cb').checked;
    const bulkNum = parseInt(document.getElementById('add-sub-bulk-num').value) || 0;

    if (!name) return showToast("Subject name required.", "error");

    const isGlobalDuplicate = window.getAllSubjects().some(s => s.subject.toLowerCase() === name.toLowerCase());
    if (isGlobalDuplicate) return showToast("Subject already exists. Names must be unique.", "error");

    if (doBulk && bulkNum <= 0) return showToast("Please enter a valid number of chapters to bulk add.", "error");

    let chaptersToAssign = doBulk ? bulkNum : 0;
    const todayStr = Utils.formatDate(new Date());
    let todayIdx = AppState.tasks.findIndex(t => t.date === todayStr);
    if (todayIdx === -1) todayIdx = 0;

    if (doBulk) {
        ensureAvailableSlots(chaptersToAssign, track, todayIdx);
    }

    syllabusStructure[track] = syllabusStructure[track] || [];
    const nextSubOrder = syllabusStructure[track].filter(s => s.program === prog).length;
    syllabusStructure[track].push({ program: prog, subject: name, chapters: chaptersToAssign, priority: 3, order: nextSubOrder });
    window.sortAllCustomData();
    getSubjectColor(name);

    if (doBulk) {
        let currentChapter = 1;
        const key = track + 'Tasks';
        for (let i = todayIdx; i < AppState.tasks.length && currentChapter <= chaptersToAssign; i++) {
            if (AppState.tasks[i].type !== 'study') continue;
            if (Array.isArray(AppState.tasks[i][key])) {
                const bIdx = AppState.tasks[i][key].findIndex(b => b.subject === 'Revision');
                if (bIdx > -1) {
                    AppState.tasks[i][key][bIdx] = { subject: name, chapter: `Ch. ${currentChapter}`, title: `Topic ${currentChapter}`, completed: false, id: AppState.tasks[i][key][bIdx].id };
                    currentChapter++;
                }
            }
        }
        reorderSubjectChapters(track, name);
    }

    document.getElementById('add-sub-name').value = '';
    document.getElementById('add-sub-bulk-cb').checked = false;
    document.getElementById('add-sub-bulk-num').value = '';
    document.getElementById('add-sub-bulk-num').classList.add('hidden');

    recalculateTotals();
    FirebaseService.saveToCloud();

    // Unblock main thread to allow modal to close immediately before heavy render
    setTimeout(() => {
        renderUI();
        showToast(doBulk ? `Subject created and ${chaptersToAssign} chapters scheduled!` : "Subject successfully created!", "success");
    }, 50);
};

window.appendNewChapter = function () {
    const track = document.getElementById('add-ch-track').value;
    const prog = document.getElementById('add-ch-program').value;
    const subj = document.getElementById('add-ch-subject').value;
    const num = document.getElementById('add-ch-num').value;
    const title = document.getElementById('add-ch-title').value;
    const formattedCh = `Ch. ${num}`;

    if (!subj || !num || !title) return showToast("Please fill all fields.", "error");

    let isDuplicate = false;
    const key = track + 'Tasks';
    for (let i = 0; i < AppState.tasks.length; i++) {
        if (AppState.tasks[i].type !== 'study') continue;
        if (Array.isArray(AppState.tasks[i][key]) && AppState.tasks[i][key].some(b => b.subject === subj && b.chapter === formattedCh)) { isDuplicate = true; break; }
    }
    if (isDuplicate) return showToast(`Chapter ${num} already exists for ${subj}!`, "error");

    const todayStr = Utils.formatDate(new Date()); let todayIdx = AppState.tasks.findIndex(t => t.date === todayStr); if (todayIdx === -1) todayIdx = 0;

    ensureAvailableSlots(1, track, todayIdx);

    let slotted = false;

    for (let i = todayIdx; i < AppState.tasks.length; i++) {
        if (AppState.tasks[i].type !== 'study') continue;
        if (Array.isArray(AppState.tasks[i][key])) {
            const bIdx = AppState.tasks[i][key].findIndex(b => b.subject === 'Revision');
            if (bIdx > -1) {
                AppState.tasks[i][key][bIdx] = { subject: subj, chapter: formattedCh, title: title, completed: false, id: AppState.tasks[i][key][bIdx].id }; slotted = true; break;
            }
        }
    }

    if (!slotted) return showToast("No upcoming 'Revision' slots left for this track!", "error");

    reorderSubjectChapters(track, subj);
    const targetSub = (syllabusStructure[track] || []).find(s => s.subject === subj);
    if (targetSub) targetSub.chapters++;

    recalculateTotals(); FirebaseService.saveToCloud(); renderUI();
    document.getElementById('add-ch-num').value = ''; document.getElementById('add-ch-title').value = '';
    showToast("Chapter added and sequenced!", "success");
};

window.appendNewAction = function () {
    const title = document.getElementById('add-act-title').value.trim();
    const desc = document.getElementById('add-act-desc').value.trim();
    const color = document.getElementById('add-act-color').value;
    const icon = document.getElementById('add-act-icon').value;
    const trackSelect = document.getElementById('add-act-track');
    const trackVal = trackSelect ? trackSelect.value : '';

    if (!title || !desc) return showToast("Please provide a Title and Description.", "error");
    const newId = 'act_' + title.toLowerCase().replace(/[^a-z0-9]/g, '') + Date.now().toString().slice(-4);

    const nextOrder = window.customActions.length;
    window.customActions.push({
        id: newId,
        title: title,
        desc: desc,
        color: color,
        icon: icon,
        priority: 3,
        order: nextOrder,
        track: trackVal || null
    });
    window.sortAllCustomData();

    document.getElementById('add-act-title').value = '';
    document.getElementById('add-act-desc').value = '';
    if (trackSelect) trackSelect.value = '';
    FirebaseService.saveToCloud(); renderUI(); showToast("Daily Action Tracker created!", "success");
};

// --- Outcomes Program Visibility Logic ---
window.renderOutcomeProgramToggles = function () {
    const bar = document.getElementById('outcome-programs-toggle-bar');
    if (!bar) return;

    if (!window.programVisibility) {
        window.programVisibility = {};
        window.getAllPrograms().forEach(pObj => {
            const pName = pObj.name || pObj;
            window.programVisibility[pName] = true;
        });
    }

    let html = '';
    window.getAllPrograms().forEach(pObj => {
        const pName = pObj.name || pObj;
        const active = window.programVisibility[pName] !== false;
        const color = window.getProgramColor(pName);

        const activeStyle = active
            ? `background-color: ${color}; color: white; border-color: ${color};`
            : `background-color: transparent; border-color: #cbd5e1; color: #64748b; opacity: 0.6;`;

        html += `
                <button onclick="window.toggleOutcomeProgram('${pName.replace(/'/g, "\\'")}')" 
                    class="px-3 py-1.5 rounded-full border text-[10px] font-black uppercase tracking-wider transition-all duration-300 active:scale-95 flex items-center gap-1.5 shadow-sm" 
                    style="${activeStyle}">
                    <span class="w-1.5 h-1.5 rounded-full ${active ? 'bg-white' : 'bg-slate-400'}"></span>
                    <span>${pName}</span>
                </button>`;
    });

    bar.innerHTML = html;
};

window.toggleOutcomeProgram = function (pName) {
    if (!window.programVisibility) window.programVisibility = {};
    window.programVisibility[pName] = !window.programVisibility[pName];

    // Sync with chart visibility as well!
    if (window.chartVisibility && window.chartVisibility.prog) {
        window.chartVisibility.prog[pName] = window.programVisibility[pName];
        // Update chart
        if (window.mainChartPrograms) {
            const ds = window.mainChartPrograms.data.datasets.find(d => d.label === pName);
            if (ds) ds.hidden = !window.programVisibility[pName];
            window.mainChartPrograms.update();
        }
    }

    // Save and re-render everything
    FirebaseService.saveToCloud();
    renderUI();
};

