window.renderTrackList = function () {
    const container = document.getElementById('sys-content-track');
    if (!container) return;

    let html = `
            <p class="text-xs text-slate-500 dark:text-slate-400 mb-6 font-bold">Add, rename, or delete academic or professional tracks. WARNING: Deleting a track deletes all its programs, subjects, and study progress data.</p>
            <div class="grid grid-cols-1 lg:grid-cols-3 gap-6 items-start">
                <!-- Add Track Card -->
                <div class="bg-slate-50 dark:bg-slate-900/50 p-5 rounded-2xl border border-slate-100 dark:border-slate-800">
                    <h4 class="text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-200 dark:border-slate-700 pb-2 mb-3">Add New Track</h4>
                    <div class="flex flex-col gap-3">
                        <div class="flex flex-col gap-1.5">
                            <label class="text-[10px] font-black uppercase tracking-widest text-slate-400">Track Name</label>
                            <input type="text" id="add-track-name" placeholder="e.g. Postgraduate (MBA)"
                                class="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg p-2.5 text-xs text-slate-900 dark:text-white focus:ring-2 focus:ring-blue-500 font-bold w-full">
                        </div>
                        <button onclick="window.appendNewTrack()"
                            class="bg-blue-600 hover:bg-blue-700 text-white font-black text-[10px] md:text-[11px] uppercase tracking-widest py-3 rounded-xl transition-all active:scale-95 shadow-md flex items-center justify-center gap-2">
                            <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"></path></svg>
                            Add Track
                        </button>
                    </div>
                </div>

                <!-- Existing Tracks List -->
                <div class="lg:col-span-2 bg-slate-50 dark:bg-slate-900/50 p-5 rounded-2xl border border-slate-100 dark:border-slate-800">
                    <h4 class="text-[10px] font-black uppercase tracking-widest text-slate-400 border-b border-slate-200 dark:border-slate-700 pb-2 mb-3">Existing Tracks</h4>
                    <div class="flex flex-col gap-3 max-h-[500px] overflow-y-auto custom-scrollbar pr-2">
            `;

    window.tracks.forEach(track => {
        const totalPrograms = window.customPrograms[track.id] ? window.customPrograms[track.id].length : 0;
        const totalSubjects = syllabusStructure[track.id] ? syllabusStructure[track.id].length : 0;

        html += `
                <div class="flex items-center justify-between p-3.5 rounded-xl bg-white dark:bg-slate-800 border border-slate-200/60 dark:border-slate-700/60 shadow-sm transition-all hover:border-blue-400">
                    <div class="flex flex-col min-w-0 pr-2 flex-1">
                        <span class="text-xs font-black text-slate-800 dark:text-slate-200 break-words whitespace-normal leading-normal">${track.name}</span>
                        <div class="flex flex-wrap items-center gap-2 mt-1">
                            <span class="text-[8px] font-bold text-slate-400 uppercase tracking-widest">ID: ${track.id}</span>
                            <span class="w-1 h-1 bg-slate-300 dark:bg-slate-600 rounded-full"></span>
                            <span class="text-[8px] font-bold text-slate-400 uppercase tracking-widest">${totalPrograms} Programs</span>
                            <span class="w-1 h-1 bg-slate-300 dark:bg-slate-600 rounded-full"></span>
                            <span class="text-[8px] font-bold text-slate-400 uppercase tracking-widest">${totalSubjects} Subjects</span>
                        </div>
                    </div>
                    <div class="flex items-center space-x-2 shrink-0 ml-2">
                        <button onclick="window.editTrackName('${track.id}')"
                            class="p-2 text-[10px] font-black uppercase tracking-widest rounded-lg bg-slate-100 hover:bg-slate-200 dark:bg-slate-700 dark:hover:bg-slate-600 text-slate-600 dark:text-slate-300 transition-all active:scale-95"
                            title="Rename Track">Rename</button>
                        <button onclick="window.requestDeleteTrack('${track.id}')"
                            class="p-2 text-[10px] font-black uppercase tracking-widest rounded-lg bg-red-50 hover:bg-red-100 dark:bg-red-500/10 dark:hover:bg-red-500/20 text-red-600 dark:text-red-400 transition-all active:scale-95"
                            title="Delete Track">Delete</button>
                    </div>
                </div>`;
    });

    html += `
                    </div>
                </div>
            </div>
            `;

    container.innerHTML = html;
};

window.appendNewTrack = function () {
    const nameInput = document.getElementById('add-track-name');
    const name = nameInput.value.trim();
    if (!name) return showToast("Track name required.", "error");

    const id = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
    if (!id) return showToast("Invalid track name.", "error");

    if (window.tracks.some(t => t.id === id)) {
        return showToast("A track with this ID or name already exists.", "error");
    }

    // Update State
    window.tracks.push({ id: id, name: name });
    window.customPrograms[id] = [];
    syllabusStructure[id] = [];

    // Backfill tasks: Loop through all existing AppState.tasks and add the new track properties
    if (Array.isArray(AppState.tasks)) {
        AppState.tasks.forEach(task => {
            if (task.type === 'study') {
                if (task[id + 'Study'] === undefined) {
                    task[id + 'Study'] = false;
                }
                const key = id + 'Tasks';
                if (!task[key]) {
                    task[key] = [{ subject: "Revision", chapter: "Rev", title: "Practice", completed: false, id: `${id}-${task.id}` }];
                }
            } else if (task.type === 'holiday') {
                if (task[id + 'Study'] === undefined) {
                    task[id + 'Study'] = false;
                }
            }
        });
    }

    nameInput.value = '';
    FirebaseService.saveToCloud();
    window.populateTrackDropdowns();
    renderUI();
    window.renderTrackList();
    showToast(`Track "${name}" successfully created!`, "success");
};

window.editTrackName = function (id) {
    const track = window.tracks.find(t => t.id === id);
    if (!track) return;

    document.getElementById('etm-track-id').value = id;
    document.getElementById('etm-track-name').value = track.name;
    openModal('edit-track-modal');
};

window.saveTrackEditModal = function () {
    const id = document.getElementById('etm-track-id').value;
    const newName = document.getElementById('etm-track-name').value.trim();
    if (!newName) return showToast("Track name cannot be empty.", "error");

    const track = window.tracks.find(t => t.id === id);
    if (!track) return;

    track.name = newName;
    FirebaseService.saveToCloud();
    window.populateTrackDropdowns();
    renderUI();
    window.renderTrackList();
    closeModal('edit-track-modal');
    showToast("Track renamed successfully!", "success");
};

window.requestDeleteTrack = function (id) {
    const track = window.tracks.find(t => t.id === id);
    if (!track) return;

    window.openConfirmModal(
        "Delete Track",
        `Are you sure you want to completely delete the track "${track.name}"? This will delete all its programs, subjects, and daily task data. This action cannot be undone.`,
        () => {
            window.executeDeleteTrack(id);
        }
    );
};

window.executeDeleteTrack = function (id) {
    const track = window.tracks.find(t => t.id === id);
    if (!track) return;

    // Gather associated programs and subjects to clean them up from global configs
    const programsToCleanup = (window.customPrograms[id] || []).map(p => p.name || p);
    const subjectsToCleanup = (syllabusStructure[id] || []).map(s => s.subject);

    // Remove from tracks
    window.tracks = window.tracks.filter(t => t.id !== id);

    // Clean up AppState.customActions track association
    if (Array.isArray(window.customActions)) {
        window.customActions.forEach(a => {
            if (a.track === id) a.track = null;
        });
    }

    // Clean up customPrograms & syllabusStructure
    if (window.customPrograms[id]) delete window.customPrograms[id];
    if (syllabusStructure[id]) delete syllabusStructure[id];

    // Remove from AppState.tasks properties
    const keyTasks = id + 'Tasks';
    const keyStudy = id + 'Study';
    if (Array.isArray(AppState.tasks)) {
        AppState.tasks.forEach(task => {
            if (task[keyTasks]) delete task[keyTasks];
            if (task[keyStudy] !== undefined) delete task[keyStudy];
        });
    }

    // Cleanup AppState.passedItems
    if (window.passedItems) {
        if (window.passedItems.programs) {
            window.passedItems.programs = window.passedItems.programs.filter(p => !programsToCleanup.includes(p));
        }
        if (window.passedItems.subjects) {
            window.passedItems.subjects = window.passedItems.subjects.filter(s => !subjectsToCleanup.includes(s));
        }
    }

    // Cleanup AppState.revisionData
    if (window.revisionData) {
        if (window.revisionData.active) {
            window.revisionData.active = window.revisionData.active.filter(s => !subjectsToCleanup.includes(s));
        }
        if (window.revisionData.progress) {
            subjectsToCleanup.forEach(sub => {
                if (window.revisionData.progress[sub]) delete window.revisionData.progress[sub];
            });
        }
    }

    // Cleanup AppState.subjectTimeLinks
    if (window.subjectTimeLinks) {
        subjectsToCleanup.forEach(sub => {
            if (window.subjectTimeLinks[sub]) delete window.subjectTimeLinks[sub];
        });
    }

    // Cleanup AppState.successResults
    if (window.successResults) {
        window.successResults = window.successResults.filter(r => {
            if (r.type === 'cgpa') {
                if (programsToCleanup.includes(r.title)) return false;
                if (r.subject && subjectsToCleanup.includes(r.subject)) return false;
            }
            return true;
        });
    }

    // Cleanup AppState.paceGoals
    if (window.paceGoals) {
        window.paceGoals = window.paceGoals.filter(g => {
            if (g.type === 'program' && programsToCleanup.includes(g.target)) return false;
            if (g.type === 'subject' && subjectsToCleanup.includes(g.target)) return false;
            return true;
        });
        window.paceGoals.forEach(g => {
            if (g.type === 'bundle') {
                if (g.programs) g.programs = g.programs.filter(p => !programsToCleanup.includes(p));
                if (g.subjects) g.subjects = g.subjects.filter(s => !subjectsToCleanup.includes(s));
            } else if (g.type === 'global') {
                if (g.subjects) g.subjects = g.subjects.filter(s => !subjectsToCleanup.includes(s));
            }
        });
        // Remove empty bundles
        window.paceGoals = window.paceGoals.filter(g => {
            if (g.type === 'bundle' && (!g.programs || g.programs.length === 0) && (!g.subjects || g.subjects.length === 0)) return false;
            return true;
        });
    }

    // Cleanup AppState.subjectDetailsState
    if (window.subjectDetailsState) {
        subjectsToCleanup.forEach(sub => {
            const safeSubId = sub.replace(/[^a-zA-Z0-9]/g, '-');
            if (window.subjectDetailsState[safeSubId] !== undefined) {
                delete window.subjectDetailsState[safeSubId];
            }
        });
    }

    // Save to cloud, repopulate, and redraw
    FirebaseService.saveToCloud();
    window.populateTrackDropdowns();
    renderUI();
    if (AppState.currentFilter && (programsToCleanup.includes(AppState.currentFilter) || subjectsToCleanup.includes(AppState.currentFilter))) {
        AppState.currentFilter = 'All';
        renderUI();
    }
    window.renderTrackList();
    showToast(`Track "${track.name}" and all associated data deleted.`, "success");
};

window.toggleMobileSidebar = function () {
    const sidebar = document.getElementById('sidebar-container');
    const backdrop = document.getElementById('sidebar-backdrop');
    if (sidebar) {
        const isOpen = sidebar.classList.contains('translate-x-0');
        if (isOpen) {
            sidebar.classList.remove('translate-x-0');
            sidebar.classList.add('-translate-x-full');
            if (backdrop) {
                backdrop.classList.add('opacity-0', 'pointer-events-none');
                backdrop.classList.remove('opacity-100');
            }
        } else {
            sidebar.classList.remove('-translate-x-full');
            sidebar.classList.add('translate-x-0');
            if (backdrop) {
                backdrop.classList.remove('opacity-0', 'pointer-events-none');
                backdrop.classList.add('opacity-100');
            }
        }
    }
};

window.closeMobileSidebar = function () {
    const sidebar = document.getElementById('sidebar-container');
    const backdrop = document.getElementById('sidebar-backdrop');
    if (sidebar) {
        sidebar.classList.remove('translate-x-0');
        sidebar.classList.add('-translate-x-full');
    }
    if (backdrop) {
        backdrop.classList.add('opacity-0', 'pointer-events-none');
        backdrop.classList.remove('opacity-100');
    }
};

window.switchPage = function (pageId) {
    const pages = ['dashboard', 'spectra-analytics', 'fiscal-ledger', 'timer', 'daily-actions', 'schedule', 'subjects', 'paces-management', 'master-config', 'outcome', 'exam'];
    pages.forEach(p => {
        const el = document.getElementById(`page-${p}`);
        if (el) {
            if (p === pageId) {
                el.classList.remove('hidden');
                el.classList.add('animate-page-enter');
            } else {
                el.classList.add('hidden');
                el.classList.remove('animate-page-enter');
            }
        }
    });

    const buttons = {
        'dashboard': { active: 'bg-slate-900 dark:bg-blue-600 text-white border-slate-900 dark:border-blue-600 shadow-lg', hover: 'hover:border-blue-400' },
        'spectra-analytics': { active: 'bg-gradient-to-r from-fuchsia-600 to-pink-600 text-white border-transparent shadow-lg shadow-fuchsia-500/20', hover: 'hover:border-fuchsia-400' },
        'fiscal-ledger': { active: 'bg-teal-600 text-white border-teal-600 shadow-lg', hover: 'hover:border-teal-400' },
        'daily-actions': { active: 'bg-orange-500 text-white border-orange-500 shadow-lg', hover: 'hover:border-orange-400' },
        'subjects': { active: 'bg-violet-600 text-white border-violet-600 shadow-lg', hover: 'hover:border-violet-400' },
        'paces-management': { active: 'bg-red-600 text-white border-red-600 shadow-lg', hover: 'hover:border-red-400' },
        'master-config': { active: 'bg-indigo-600 text-white border-indigo-600 shadow-lg', hover: 'hover:border-indigo-400' },
        'outcome': { active: 'bg-yellow-500 text-white border-yellow-500 shadow-lg', hover: 'hover:border-yellow-400' },
        'timer': { active: 'bg-emerald-600 text-white border-emerald-600 shadow-lg', hover: 'hover:border-emerald-400' },
        'schedule': { active: 'bg-cyan-600 text-white border-cyan-600 shadow-lg', hover: 'hover:border-cyan-400' },
        'exam': { active: 'bg-rose-600 text-white border-rose-600 shadow-lg', hover: 'hover:border-rose-400' }
    };

    pages.forEach(p => {
        const btn = document.getElementById(`btn-nav-${p}`);
        if (btn) {
            const baseClass = "w-full border-2 px-4 py-3 rounded-2xl font-black text-xs transition-all duration-300 hover:translate-x-1.5 hover:shadow-md active:scale-98 flex items-center gap-3";
            if (p === pageId) {
                btn.className = `${baseClass} ${buttons[p].active}`;
            } else {
                btn.className = `${baseClass} bg-white dark:bg-slate-800 border-slate-100 dark:border-slate-700 text-slate-600 dark:text-slate-300 ${buttons[p].hover}`;
            }
        }
    });

    if (pageId === 'exam' && typeof window.renderExamPage === 'function') {
        window.renderExamPage();
    }

    const contentPanel = document.getElementById('main-content-panel');
    if (contentPanel) {
        contentPanel.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    // Handle chart resizing or rendering when visible
    if (pageId === 'dashboard' || pageId === 'spectra-analytics') {
        const resizeAndUpdateAll = () => {
            const charts = [
                window.mainChartPrograms,
                window.monthlyChartActions,
                window.yearlyChartActions,
                window.spectraPaceTrendChartInstance,
                window.globalPaceTrendChartInstance,
                window.dbProgressChartInstance,
                window.spectraFocusAnalyticsChartInstance,
                window.timerAnalyticsChartInstance
            ];
            charts.forEach(chart => {
                if (chart && typeof chart.resize === 'function') {
                    chart.resize();
                    if (typeof chart.update === 'function') {
                        chart.update('none');
                    }
                }
            });
        };
        // Resize early during transition
        setTimeout(resizeAndUpdateAll, 50);
        // Resize and repaint again after entry transition completes (400ms animation) to prevent GPU caching/blank canvas bugs
        setTimeout(resizeAndUpdateAll, 420);

        if (window.renderSpectraFocusHeatmap) setTimeout(window.renderSpectraFocusHeatmap, 50);

        if (pageId === 'spectra-analytics') {
            if (window.updateTimerAnalyticsControls) setTimeout(window.updateTimerAnalyticsControls, 50);
            if (window.renderSpectraCircleChart) setTimeout(window.renderSpectraCircleChart, 50);
            if (window.renderTimerAnalyticsChart) setTimeout(window.renderTimerAnalyticsChart, 50);
            if (window.renderSpectraCommitmentsChart) setTimeout(window.renderSpectraCommitmentsChart, 50);
        }
        } else if (pageId === 'subjects') {
        if (typeof renderSubjectNavigation === 'function') renderSubjectNavigation();
        if (typeof renderCategoryProgress === 'function') renderCategoryProgress(typeof latestChartStats !== 'undefined' && latestChartStats?.subjects ? latestChartStats.subjects : {});
        setTimeout(() => {
            if (AppState.progressChart) {
                const oldData = AppState.progressChart.data.datasets[0].data.slice();
                AppState.progressChart.destroy();
                const canvas = document.getElementById('progressChart');
                if (canvas) {
                    AppState.progressChart = new Chart(canvas.getContext('2d'), {
                        type: 'doughnut',
                        data: { datasets: [{ data: oldData, backgroundColor: ['#3b82f6', 'rgba(148, 163, 184, 0.1)'], borderWidth: 0 }] },
                        options: { responsive: true, maintainAspectRatio: false, cutout: '82%', plugins: { legend: { display: false }, tooltip: { enabled: false } } }
                    });
                }
            }
        }, 50);
    } else if (pageId === 'daily-actions') {
        if (typeof renderDailyTracker === 'function') renderDailyTracker();
        if (typeof renderDailyLogs === 'function') renderDailyLogs();
    } else if (pageId === 'paces-management') {
        if (typeof window.renderPaceGoals === 'function') window.renderPaceGoals(typeof latestChartStats !== 'undefined' && latestChartStats?.subjects ? latestChartStats.subjects : {});
    } else if (pageId === 'outcome') {
        if (typeof window.renderResults === 'function') window.renderResults();
        setTimeout(() => {
            if (window.resultsTrendChartInstance) window.resultsTrendChartInstance.resize();
        }, 50);
    } else if (pageId === 'master-config') {
        if (typeof window.populateTrackDropdowns === 'function') window.populateTrackDropdowns();
        if (typeof window.updateManageDropdown === 'function') window.updateManageDropdown();
        if (typeof window.renderPassConfig === 'function') window.renderPassConfig();
        if (typeof window.renderPriorityConfig === 'function') window.renderPriorityConfig();

    } else if (pageId === 'schedule') {
        window.renderSchedulePage();
    } else if (pageId === 'fiscal-ledger') {
        if (typeof window.renderFiscalLedgerPage === 'function') window.renderFiscalLedgerPage();
    }

    if (pageId === 'dashboard') {
        if (typeof renderUI === 'function') {
            renderUI();
        }
    }
};

document.addEventListener('DOMContentLoaded', async () => {
    if (!document.getElementById('app-wrapper')) return;
    if (AppState.isAppInitialized) return;
    // Loading screen safety fallback timer (3s max)
    setTimeout(() => {
        if (typeof window.dismissLoadingScreen === 'function') {
            window.dismissLoadingScreen();
        } else {
            const loadingEl = document.getElementById('auth-loading');
            const wrapperEl = document.getElementById('app-wrapper');
            if (loadingEl) loadingEl.remove();
            if (wrapperEl) wrapperEl.classList.remove('hidden');
        }
    }, 3000);

    // Dismiss tooltips on document click
    document.addEventListener('click', () => {
        if (window.hideChapterTooltip) window.hideChapterTooltip();
        if (window.hideSubjectChapterTooltip) window.hideSubjectChapterTooltip();
        if (window.hideSpectraChapterTooltip) window.hideSpectraChapterTooltip();
    });

    // Initialize Focus Timer Service
    if (window.TimerService) {
        window.TimerService.init();
    }

    // Start progress
    if (window.setLoadingProgress) window.setLoadingProgress(15, 'Initializing workspace...');

    // Load configurations & Initialize Firebase Service
    try {
        const config = await FirebaseService.fetchConfig();
        if (window.setLoadingProgress) window.setLoadingProgress(40, 'Connecting to server...');
        FirebaseService.init(config);
        if (window.setLoadingProgress) window.setLoadingProgress(55, 'Authenticating session...');
    } catch (e) {
        console.error("Firebase init failed:", e);
    }

    // Route guard
    FirebaseService.onAuthStateChanged(async (user) => {
        if (!user) {
            window.location.href = 'login.html';
            return;
        }

        if (user.email !== 'ris2k29@gmail.com') {
            FirebaseService.logout().then(() => {
                window.location.href = 'login.html?error=denied';
            });
            return;
        }

        // Authorized
        console.log("Admin authorized:", user.email);
        window.currentUser = user;
        if (window.setLoadingProgress) window.setLoadingProgress(70, 'Loading cloud workspace...');

        // Update profile section
        const displayName = user.displayName || 'ris2k29';
        const displayEmail = user.email;

        const profileNameEl = document.getElementById('profile-name');
        const profileEmailEl = document.getElementById('profile-email');
        const profileAvatarEl = document.getElementById('profile-avatar');
        if (profileNameEl) profileNameEl.textContent = displayName;
        if (profileEmailEl) profileEmailEl.textContent = displayEmail;
        if (profileAvatarEl) {
            profileAvatarEl.textContent = displayName.charAt(0).toUpperCase();
        }

        // Subscribe and sync from cloud
        FirebaseService.loadFromCloud();
        window.switchPage('dashboard');
    });

    // --- Progressive Web App (PWA) Logic ---
    let deferredPrompt = null;
    const installBtn = document.getElementById('pwa-install-btn');

    window.addEventListener('beforeinstallprompt', (e) => {
        e.preventDefault();
        deferredPrompt = e;
        if (installBtn) {
            installBtn.classList.remove('hidden');
            installBtn.classList.add('flex');
        }
        console.log("[PWA] beforeinstallprompt event fired.");
    });

    if (installBtn) {
        installBtn.addEventListener('click', async () => {
            if (!deferredPrompt) return;
            deferredPrompt.prompt();
            const { outcome } = await deferredPrompt.userChoice;
            console.log(`[PWA] User response to install prompt: ${outcome}`);
            if (outcome === 'accepted') {
                installBtn.classList.add('hidden');
                installBtn.classList.remove('flex');
            }
            deferredPrompt = null;
        });
    }

    window.addEventListener('appinstalled', (evt) => {
        console.log('[PWA] Project X was installed successfully!');
        if (installBtn) {
            installBtn.classList.add('hidden');
            installBtn.classList.remove('flex');
        }
        if (typeof showToast === 'function') {
            showToast('Project X Installed Successfully!', 'success');
        }
    });

    // Clear existing service workers and caches from existing users
    if ('serviceWorker' in navigator) {
        navigator.serviceWorker.getRegistrations().then(registrations => {
            registrations.forEach(registration => registration.unregister());
        });
        caches.keys().then(names => {
            names.forEach(name => caches.delete(name));
        });
    }
});

/******************************************************************
 * LOGIN AUTH
 ******************************************************************/
document.addEventListener('DOMContentLoaded', async () => {
    if (!document.getElementById('login-form')) return;
    const loginForm = document.getElementById('login-form');
    const emailInput = document.getElementById('email');
    const passwordInput = document.getElementById('password');
    const btnSubmit = document.getElementById('btn-submit');
    const spinner = document.getElementById('spinner');
    const errorBanner = document.getElementById('error-banner');
    const errorMessage = document.getElementById('error-message');

    // Show error banner if redirected with error
    const params = new URLSearchParams(window.location.search);
    if (params.get('error') === 'denied') {
        showError("Access denied. Project X is private.");
    }

    function showError(msg) {
        errorMessage.textContent = msg;
        errorBanner.classList.remove('hidden');
    }

    function hideError() {
        errorBanner.classList.add('hidden');
    }

    // Load configurations & Initialize Firebase
    let config;
    try {
        config = await FirebaseService.fetchConfig();
        FirebaseService.init(config);
        console.log("Firebase initialized for login.");
    } catch (e) {
        console.error("Firebase init error:", e);
        showError("Firebase initialization failed.");
        return;
    }

    // Route guard checking if user is already logged in as admin
    FirebaseService.onAuthStateChanged((user) => {
        if (user && user.email === 'ris2k29@gmail.com') {
            window.location.href = 'index.html';
        }
    });

    // Handle Form Submission
    loginForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        hideError();

        const email = emailInput.value.trim();
        const password = passwordInput.value;

        btnSubmit.disabled = true;
        spinner.classList.remove('hidden');

        try {
            const userCredential = await FirebaseService.login(email, password);
            const user = userCredential.user;

            if (user.email !== 'ris2k29@gmail.com') {
                await FirebaseService.logout();
                showError("Access denied. Project X is private.");
                btnSubmit.disabled = false;
                spinner.classList.add('hidden');
            } else {
                window.location.href = 'index.html';
            }
        } catch (error) {
            console.error("Auth error:", error);
            let friendlyMsg = "Authentication failed. Please check your credentials.";
            if (error.code === 'auth/wrong-password' || error.code === 'auth/user-not-found' || error.code === 'auth/invalid-credential') {
                friendlyMsg = "Invalid email or password.";
            } else if (error.code === 'auth/invalid-email') {
                friendlyMsg = "Invalid email address format.";
            } else if (error.code === 'auth/user-disabled') {
                friendlyMsg = "This user account has been disabled.";
            }
            showError(friendlyMsg);
            btnSubmit.disabled = false;
            spinner.classList.add('hidden');
        }
    });

    // Clear existing service workers and caches from existing users
    if ('serviceWorker' in navigator) {
        navigator.serviceWorker.getRegistrations().then(registrations => {
            registrations.forEach(registration => registration.unregister());
        });
        caches.keys().then(names => {
            names.forEach(name => caches.delete(name));
        });
    }
});

// Clear existing service workers and caches from existing users
if ('serviceWorker' in navigator) {
    navigator.serviceWorker.getRegistrations().then(registrations => {
        registrations.forEach(registration => registration.unregister());
    });
    caches.keys().then(names => {
        names.forEach(name => caches.delete(name));
    });
}


